const publishDialog=document.createElement('dialog');
publishDialog.id='publish-dialog';publishDialog.setAttribute('aria-labelledby','publish-heading');
publishDialog.innerHTML=`<div class="dialog-head"><span>CREATOR STUDIO</span><button type="button" id="close-publish" aria-label="Close publisher">✕</button></div><h2 id="publish-heading">Turn your idea into an experience.</h2><p>Invite people into your world with a playable Slice.</p><div class="publish-notice">Local prototype · Saved in this browser, including after refresh. Not yet public.</div><form id="publish-form"><div class="publish-grid"><div class="publish-fields"><label>Slice title <input name="title" required maxlength="50" placeholder="Name your experience"></label><label>Short description <textarea name="description" required maxlength="160" rows="3" placeholder="What can people try and discover?"></textarea></label><label>Categories <select name="category">${cats.slice(1).map(c=>`<option>${c}</option>`).join('')}</select></label><label>Interactive Slice <select name="template"><option value="beat">Rhythm challenge · Catch the light</option><option value="orbit">Orbit experiment · Adjust gravity</option><option value="quiz">Probability quiz · Make a choice</option><option value="wave">Wave superposition · Adjust frequency</option><option value="draw">Symmetry drawing · Drag to draw</option><option value="social">Superpower choice · Pick a side</option></select></label><span class="field-help">Choose a playable template, or import interactive HTML.</span><label>Slicer name <input name="author" required maxlength="30" value="Curious Slicer"></label></div><div class="publish-preview"><div class="preview-label">FEED PREVIEW <span>TRY IT HERE</span></div><div id="publish-slice"></div><h3 id="preview-title">Your next playable idea</h3><p id="preview-desc">Describe what people can try and discover.</p><span id="preview-author">Curious Slicer</span></div></div><p id="publish-error" role="alert"></p><div class="dialog-bottom"><button type="button" id="save-draft">Save draft</button><button type="submit" class="dark">Publish locally ↗</button></div></form>`;
document.body.append(publishDialog);
const publishForm=document.querySelector('#publish-form');const storageKey='slice-local-works-v1',draftKey='slice-publish-draft-v1';const templates=['beat','orbit','quiz','wave','draw','social'];
function readStored(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
function formData(){const f=new FormData(publishForm);return {title:String(f.get('title')).trim(),desc:String(f.get('description')).trim(),cat:String(f.get('category')),template:String(f.get('template')),author:String(f.get('author')).trim()}}
function updatePublishPreview(reset=false){const d=formData();document.querySelector('#preview-title').textContent=d.title||'Your next playable idea';document.querySelector('#preview-desc').textContent=d.desc||'Describe what people can try and discover.';document.querySelector('#preview-author').textContent=d.author||'Curious Slicer';const host=document.querySelector('#publish-slice');if(reset||host.dataset.template!==d.template){host.dataset.template=d.template;const source=works.find(w=>w.id===d.template);host.innerHTML=stage(source);initStages(host)}}
document.querySelector('#publish-entry').onclick=()=>{const d=readStored(draftKey,null);if(d){for(const [name,key] of [['title','title'],['description','desc'],['category','cat'],['template','template'],['author','author']])if(typeof d[key]==='string')publishForm.elements[name].value=d[key]}document.querySelector('#publish-error').textContent='';publishDialog.showModal();updatePublishPreview(true)};
document.querySelector('#close-publish').onclick=()=>publishDialog.close();publishForm.addEventListener('input',()=>updatePublishPreview());
document.querySelector('#save-draft').onclick=()=>{try{localStorage.setItem(draftKey,JSON.stringify(formData()));toast('Draft saved in this browser.')}catch{document.querySelector('#publish-error').textContent='Storage is unavailable. Check your browser settings and try again.'}};
publishForm.onsubmit=e=>{e.preventDefault();const d=formData();if(!d.title||!d.desc||!d.author){document.querySelector('#publish-error').textContent='Enter a title, description, and Slicer name. Blank spaces are not enough.';return}if(!isPublishableWork(d)){document.querySelector('#publish-error').textContent='Only playable experiences can be published. Choose an interactive template or import interactive HTML.';return}const source=works.find(w=>w.id===d.template);const work={...d,contentType:'interactive',id:'local-'+crypto.randomUUID(),local:true,bg:source.bg,time:'Published locally',likes:0,plays:'0'};try{const stored=readStored(storageKey,[]);const entries=Array.isArray(stored)?stored:[];localStorage.setItem(storageKey,JSON.stringify([work,...entries]));localStorage.removeItem(draftKey)}catch{document.querySelector('#publish-error').textContent='Slice was not published. Check available browser storage and try again.';return}works.unshift(work);searchQuery='';const searchField=document.querySelector('#slice-search');if(searchField)searchField.value='';selected='All';document.querySelectorAll('[data-cat]').forEach(b=>{b.classList.toggle('selected',b.dataset.cat==='All');b.setAttribute('aria-pressed',b.dataset.cat==='All')});render();publishDialog.close();publishForm.reset();document.querySelector('#card-'+work.id).scrollIntoView({behavior:'smooth',block:'center'});toast('Published locally. Your experience will remain after refresh.')};
const saved=readStored(storageKey,[]);if(Array.isArray(saved)){const valid=saved.filter(w=>w&&isPublishableWork(w)&&/^local-[a-z0-9-]+$/.test(w.id)&&templates.includes(w.template)&&cats.slice(1).includes(w.cat)&&['title','desc','author'].every(k=>typeof w[k]==='string')&&/^#[0-9a-f]{6}$/i.test(w.bg)).map(w=>({...w,contentType:'interactive',local:true,likes:0,plays:'0',time:'Published locally'}));works.unshift(...valid);render()}
